import{_ as a,y as i,a as l,o as h,a2 as n,D as o,g as r,I as s}from"./chunks/framework.DCcmcJcL.js";const C=JSON.parse('{"title":"Content","description":"","frontmatter":{},"headers":[],"relativePath":"configure/content.md","filePath":"configure/content.md","lastUpdated":1789441803000}'),g={name:"configure/content.md"};function d(c,e,p,u,f,m){const t=i("ImagePopup");return h(),l("div",null,[e[0]||(e[0]=n('<h1 id="content" tabindex="-1">Content <a class="header-anchor" href="#content" aria-label="Permalink to &quot;Content&quot;">​</a></h1><p>The <strong>Content</strong> screen holds the promotional line at the top of the storefront, the copyright line in its footer, the speculation rules that make storefront pages open faster, and your own CSS and JavaScript.</p><h2 id="header-offer-title" tabindex="-1">Header offer title <a class="header-anchor" href="#header-offer-title" aria-label="Permalink to &quot;Header offer title&quot;">​</a></h2><p>The header offer is a short promotional line with a link, shown in the top bar of the storefront header on desktop screens. It applies to every channel and language.</p><ol><li>Go to <strong>Configure &gt;&gt; General &gt;&gt; Content</strong>.</li><li>In <strong>Header Offer Title</strong>, enter the <strong>Offer Title</strong>, up to 100 characters. The default is <code>Get UPTO 40% OFF on your 1st order</code>.</li><li>Enter the <strong>Redirection Title</strong>, the link text shown after the offer, up to 25 characters. The default is <code>SHOP NOW</code>.</li><li>Enter the <strong>Redirection Link</strong>, the page the link opens, such as <code>/womens</code>. If you leave it empty, the link opens the home page.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',5)),o(t,{src:"/images/configure/content-header-offer.png",alt:"Header Offer Title and Copyright Content sections of the Content screen"}),o(t,{src:"/images/configure/content-header-offer-storefront.png",alt:"Header offer line with its SHOP NOW link in the top bar of the storefront"}),e[1]||(e[1]=n('<h2 id="copyright-content" tabindex="-1">Copyright content <a class="header-anchor" href="#copyright-content" aria-label="Permalink to &quot;Copyright content&quot;">​</a></h2><p>The copyright line is shown at the bottom of the storefront footer. It is saved per language, so choose the language at the top of the screen before you enter it, and repeat for each language your storefront offers.</p><ol><li>Go to <strong>Configure &gt;&gt; General &gt;&gt; Content</strong>.</li><li>In <strong>Copyright Content</strong>, enter the text, such as <code>© 2026 Example Store. All rights reserved.</code></li><li>Click <strong>Save Configuration</strong>.</li></ol><p>While the field is empty, the footer shows Bagisto&#39;s default line, which names Webkul Software, so enter your own line for every language. The text can include HTML, such as a link to your terms page.</p>',4)),o(t,{src:"/images/configure/content-copyright-storefront.png",alt:"Default copyright line in the storefront footer"}),e[2]||(e[2]=n('<h2 id="speculation-rules" tabindex="-1">Speculation rules <a class="header-anchor" href="#speculation-rules" aria-label="Permalink to &quot;Speculation rules&quot;">​</a></h2><p>Speculation rules tell a shopper&#39;s browser which storefront pages it may load before the shopper opens them, so the next page appears almost at once. The rules are added to storefront pages only, and browsers that don&#39;t support them ignore them. All nine settings apply to the whole store.</p><ol><li>Go to <strong>Configure &gt;&gt; General &gt;&gt; Content</strong>.</li><li>In <strong>Speculation Rules</strong>, switch <strong>Enable Speculation Rules</strong> on.</li><li>Switch on <strong>Enable Prerender Speculation Rules</strong>, <strong>Enable Prefetch Speculation Rules</strong>, or both. The settings for each appear below its switch.</li><li>Change the settings described in the table.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',3)),o(t,{src:"/images/configure/content-speculation-rules.png",alt:"Speculation Rules section with speculation, prerender and prefetch switched on"}),e[3]||(e[3]=n('<table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Enable Speculation Rules</strong></td><td>Adds the rules to storefront pages. While it&#39;s off, the settings below have no effect. Off by default.</td></tr><tr><td><strong>Enable Prerender Speculation Rules</strong></td><td>Lets the browser load and display likely next pages in the background, so they open instantly. Uses more resources than prefetching. Off by default.</td></tr><tr><td><strong>Ignore Prerender URLs</strong></td><td>Pages that are never prerendered, separated by a pipe symbol. A <code>*</code> matches any text.</td></tr><tr><td><strong>Ignore Prerender URL Parameters</strong></td><td>Query parameters, such as <code>utm_source</code>, that keep a link from being prerendered. Separate several with a pipe symbol.</td></tr><tr><td><strong>Prerender Eagerness Level</strong></td><td>When prerendering starts: <strong>Eager</strong> starts soonest, <strong>Moderate</strong> (the default) waits until the shopper points at a link, and <strong>Conservative</strong> waits until they press it.</td></tr><tr><td><strong>Enable Prefetch Speculation Rules</strong></td><td>Lets the browser download likely next pages without displaying them. Off by default.</td></tr><tr><td><strong>Ignore Prefetch URLs</strong></td><td>Pages that are never prefetched, in the same format as <strong>Ignore Prerender URLs</strong>.</td></tr><tr><td><strong>Ignore Prefetch URL Parameters</strong></td><td>Query parameters that keep a link from being prefetched, in the same format as <strong>Ignore Prerender URL Parameters</strong>.</td></tr><tr><td><strong>Prefetch Eagerness Level</strong></td><td>When prefetching starts, with the same levels as <strong>Prerender Eagerness Level</strong>.</td></tr></tbody></table><p>Both ignore lists start as <code>/customer/account/*|/checkout/*</code>, which keeps the customer account and checkout pages from being loaded in advance. To keep a page out of speculation whatever parameters its links carry, add the page itself to the ignore URLs.</p><h2 id="custom-scripts" tabindex="-1">Custom scripts <a class="header-anchor" href="#custom-scripts" aria-label="Permalink to &quot;Custom scripts&quot;">​</a></h2><p>Custom scripts add your own CSS and JavaScript to every storefront page without changing the theme, for example a color change, a chat widget or an analytics snippet. Both fields are saved per channel, so choose the channel at the top of the screen first when your store has more than one.</p><ol><li>Go to <strong>Configure &gt;&gt; General &gt;&gt; Content</strong>.</li><li>In <strong>Custom Scripts</strong>, enter your styles in <strong>Custom CSS</strong>, without <code>&lt;style&gt;</code> tags. The store adds them to the head of every page.</li><li>Enter your script in <strong>Custom Javascript</strong>, without <code>&lt;script&gt;</code> tags. The store adds it at the end of every page.</li><li>Click <strong>Save Configuration</strong>.</li><li>Reload the storefront to check the result.</li></ol>',5)),o(t,{src:"/images/configure/content-custom-scripts.png",alt:"Custom Scripts section with a sample CSS rule and an analytics script"}),e[4]||(e[4]=r("div",{class:"warning custom-block"},[r("p",{class:"custom-block-title"},"WARNING"),r("p",null,[s("A script with an error can stop storefront pages from working, so test changes on a staging store first if you have one. The "),r("strong",null,"Custom CSS"),s(" is also loaded in the admin panel, and the "),r("strong",null,"Custom Javascript"),s(" on the admin sign-in pages, so write rules and scripts that affect only the storefront's own elements.")])],-1))])}const _=a(g,[["render",d]]);export{C as __pageData,_ as default};
